{
  "name": "Aged, Blind, and Disabled Medicaid",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "overview": "Wyoming’s ABD Medicaid has multiple pathways. For standard aged/blind/disabled eligibility, the state uses SSI-related income/resource rules, and for nursing facility or HCBS waiver-related ABD, income must generally be at or below 300% of the Federal Benefit Rate/payment standard.[1][2][4]",
      "table": [
        {
          "category": "SSI-related ABD",
          "limit": "SSI-style income/resource rules; Wyoming’s materials reference SSI eligibility and SSI-related groups rather than a single universal ABD dollar limit.[1][2][4]"
        },
        {
          "category": "Institutional / nursing facility / hospice / HCBS waiver ABD",
          "limit": "Income at or below 300% of the payment standard / Federal Benefit Rate.[1][2][5][11][15]"
        }
      ],
      "notes": "The public-facing Wyoming sources found do not provide one simple statewide ABD income chart for every household type in the search snippets; the official manual and eligibility engine contain the detailed tables used by the state.[5][6][7]"
    },
    "asset_limits": {
      "overview": "ABD eligibility includes resource guidelines, and Wyoming’s official materials indicate applicants must meet the applicable resource standards for the specific ABD coverage group.[3][4][5]",
      "counts": [
        "Countable resources are evaluated under the program’s resource standards.[3][5]",
        "The detailed countable/exempt resource rules are in Wyoming Medicaid’s eligibility manual and tables.[5][6][7]"
      ],
      "exempt": [
        "The searched official snippets do not list the full exemption list in-line; the state’s eligibility manual is the controlling source for exemptions and exclusions.[5][6][7]"
      ]
    },
    "other_requirements": [
      "Must be a Wyoming resident.[1]",
      "Must be a U.S. citizen or a lawful permanent resident who has lived in the U.S. for at least five years.[1]",
      "Must be age 65 or older, blind, or disabled.[1][2][4]",
      "Disability is determined using Social Security standards or by the Wyoming Department of Health.[2][4][10]",
      "For some ABD pathways, the person must also meet a level-of-care or medical-necessity requirement, such as nursing facility or waiver level of care.[1][3][4][5]",
      "Some ABD groups are tied to SSI eligibility or loss of SSI due to specific circumstances such as COLA-related increases or widow/widower benefits.[2]"
    ]
  },
  "benefits": {
    "type": "in_kind",
    "value": "Medicaid covers medical care and certain additional services for eligible aged, blind, or disabled individuals, including office visits, outpatient and inpatient care, pharmacy, behavioral health, dental, vision in limited circumstances, long-term care/nursing facility services, home and community-based waiver services, non-emergency transportation, screenings, and treatment referrals.[11][15] Wyoming’s ABD-related materials also note adult benefits such as 2 preventive dental visits and 2 emergency dental visits per year, while routine vision is not covered except for treatment of eye disease or injury.[12]",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online: https://www.wesystem.wyo.gov/[8][10][14]",
      "Phone: 1-855-294-2127[8][9][14]",
      "TTY/TDD: 1-855-329-5204[9][14]",
      "Mail: Wyoming Department of Health, Customer Service Center, 3001 E. Pershing Blvd., Suite 125, Cheyenne, WY 82001[8][10]",
      "Paper application in person, with submission through the Customer Service Center route[8][10]"
    ],
    "processing_time": "Not clearly stated in the official snippets reviewed; no fixed processing timeline was surfaced in the search results.",
    "waitlist": "No statewide ABD Medicaid waitlist was identified in the official materials reviewed; HCBS waiver services may have separate level-of-care and waiver administration considerations.[3][5]",
    "forms": [
      "Wyoming Medicaid Application (English or Spanish)[8][10]",
      "Medicaid Eligibility Online Manual / ABD eligibility sections for rules and determinations[5][6][7]"
    ],
    "documents": [
      "Proof of identity and Wyoming residency",
      "Proof of citizenship or qualifying immigrant status",
      "Social Security number information",
      "Proof of age",
      "Proof of disability or blindness if not already established by SSA",
      "Income verification",
      "Resource/asset statements",
      "Medical records or disability evidence if disability must be established by the state",
      "Any Medicare, health insurance, or other coverage information"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Statewide Wyoming Medicaid program; no county-only ABD restriction was identified in the official materials reviewed.[1][8][13]",
    "regional_variations": "The core eligibility rules appear statewide. Differences are mainly administrative or provider-based, and waiver/long-term-care services can vary by provider network and level-of-care determinations rather than by county.[1][3][5]",
    "offices_or_providers": [
      "Wyoming Department of Health Customer Service Center, 3001 E. Pershing Blvd., Suite 125, Cheyenne, WY 82001[8][10]"
    ]
  },
  "official_source": "https://health.wyo.gov/healthcarefin/medicaid/programs-and-eligibility/",
  "gotchas": [
    "ABD Medicaid in Wyoming is not a single one-size-fits-all eligibility group; there are different ABD pathways, including SSI-related, institutional, hospice, and waiver-related coverage groups.[2][3][4][5]",
    "Income and resource rules depend on the specific ABD pathway, so families need the correct category before assuming a simple monthly limit.[2][3][5][6][7]",
    "Disability is not just self-attested; Wyoming may require SSA standards or state determination and supporting medical evidence.[2][4][10]",
    "For some long-term-care or waiver-related ABD coverage, meeting income limits is not enough because the applicant must also meet level-of-care or medical-necessity requirements.[1][3][5]",
    "Routine vision care is generally not covered; coverage is narrower than many families expect.[12]",
    "Dental coverage exists but is limited, with preventive and emergency visit limits noted in Wyoming’s adult Medicaid materials.[12]"
  ],
  "data_shape_notes": "This program is best modeled as multiple ABD coverage groups with different eligibility pathways rather than a single benefit with one universal income table. The key structure is age/blindness/disability plus SSI/resource rules, with some pathways using a 300% FBR/payment-standard cap and additional level-of-care requirements.[1][2][3][4][5][6][7][11][15]"
}

{
  "name": "Medicare Savings Programs",
  "eligibility": {
    "age": null,
    "income_limits": {
      "basis": "Countable income must be at or below the federal poverty level band for the MSP tier; Wyoming uses three tiers tied to Medicare entitlement and countable income.[1][2]",
      "table": [
        {
          "tier": "QMB",
          "income_limit": {
            "1_person": "$1,330/month",
            "2_people": "$1,804/month"
          },
          "fpl_band": "100% FPL[1][2]"
        },
        {
          "tier": "SLMB",
          "income_limit": {
            "1_person": "$1,596/month",
            "2_people": "$2,164/month"
          },
          "fpl_band": "120% FPL[1][2]"
        },
        {
          "tier": "QI",
          "income_limit": {
            "1_person": "$1,796/month",
            "2_people": "$2,435/month"
          },
          "fpl_band": "135% FPL[1][2]"
        }
      ],
      "notes": "The official Wyoming table shown in 2026 lists only household sizes 1 and 2 on the page retrieved; Wyoming applies the tier rules statewide and the limits are adjusted annually.[1][2]"
    },
    "asset_limits": {
      "limit": "Wyoming rules require countable resources not to exceed the Social Security resource limit, adjusted annually by the CPI.[2]",
      "what_counts": [
        "Bank accounts and other countable cash resources",
        "Other resources counted under SSA-style MSP rules[2]"
      ],
      "what_is_exempt": [
        "The retrieved official Wyoming sources did not spell out the full exempt-resource list on the same page.",
        "Families should verify the current treatment of a home, one vehicle, and personal effects with the state application worker before applying."
      ]
    },
    "other_requirements": [
      "Must be entitled to Medicare.[2]",
      "Must meet the income tier for QMB, SLMB, or QI.[1][2]",
      "Must meet the applicable resource standard for the tier.[2]",
      "Eligibility is for Medicare beneficiaries; no separate Wyoming residency rule was surfaced in the retrieved official MSP pages."
    ]
  },
  "benefits": {
    "type": "financial",
    "value": "QMB pays Medicare Part A and Part B premiums and also Medicare deductibles, coinsurance, and copayments. SLMB pays the Medicare Part B premium. QI also pays the Medicare Part B premium.[3][4]",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online through the Wyoming Department of Health application system (the official application process page points to the state web application path).[4]",
      "By phone at 855-294-2127 to request an application or apply with assistance.[4]",
      "By phone through the Long Term Care Unit at 855-203-2936 when applying in connection with long-term care services.[4]",
      "Pick up an application at any Department of Family Services field office.[4]",
      "Mail/fax request: request an application be mailed or faxed through the WDH Customer Service Center.[4]"
    ],
    "processing_time": "The retrieved official pages did not state a specific processing time; the application page describes the routes to apply but not a posted approval timeline.[4]",
    "waitlist": null,
    "forms": [
      "M1100 Medicare Savings Programs (eligibility section in Wyoming’s eligibility manual)",
      "Wyoming Department of Health application for benefits referenced on the application process page[2][4]"
    ],
    "documents": [
      "Medicare card",
      "Proof of monthly income such as Social Security award letter or pension statement",
      "Bank statements and other proof of countable resources",
      "Proof of Wyoming residency if requested by the worker",
      "Identification for the applicant and spouse if applicable"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Statewide Wyoming program; no county restriction surfaced in the official sources retrieved.[1][2][4]",
    "regional_variations": "No regional benefit differences were identified in the official materials retrieved. Any variation is administrative rather than programmatic, such as where a family submits the application or which local field office assists them.[4]",
    "offices_or_providers": [
      "Wyoming Department of Family Services field offices",
      "Wyoming Department of Health Customer Service Center",
      "Long Term Care Unit for LTC-related applications"
    ]
  },
  "official_source": "https://health.wyo.gov/healthcarefin/medicaid/programs-and-eligibility/medicaid-income-requirements/",
  "gotchas": [
    "People often think MSP is one program, but Wyoming actually has three tiers: QMB, SLMB, and QI.[1][2][3]",
    "QMB is the only tier that can cover Medicare cost-sharing; SLMB and QI generally pay only the Part B premium.[3]",
    "The income test uses countable income, not simply every dollar of gross income.[2]",
    "Resource rules still matter, and they are separate from the income limits.[2]",
    "The official application page gives phone and office routes, but the retrieved sources did not provide a single online form number or a posted processing-time guarantee.[4]",
    "QI is typically the most overlooked tier because its income limit is higher than SLMB but funding and enrollment rules can make it feel less straightforward than QMB or SLMB."
  ],
  "data_shape_notes": "This program is tiered by Medicare Savings category and countable income, with a separate resource test; benefits differ sharply by tier, and application routes are statewide rather than county-specific.[1][2][3][4]"
}
